dependency_order.buggy:
def dependency_order(graph):
    order = []
    while graph:
        ready = sorted(name for name in graph if not graph[name])
        if not ready:
            return order
        order.extend(ready)
        graph = {k: [p for p in v if p not in ready] for k, v in graph.items() if k not in ready}
    return order

